utton\"\n            aria-label=\"展开角色筛选\"\n            :aria-expanded=\"mobileFiltersExpanded\"\n            @click=\"toggleMobileFilters\"\n          >\n            <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n              <path d=\"M4 6h16M7 12h10M10 18h4\" />\n            </svg>\n            <span>筛选</span>\n          </button>\n          <button class=\"primary\" type=\"button\" aria-label=\"返回游戏并关闭角色资料库\" @click=\"closeCharacterLibrary\">\n            <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n              <path d=\"m4 11 8-7 8 7\" />\n              <path d=\"M6.5 10v10h11V10M9.5 20v-6h5v6\" />\n            </svg>\n            <span>返回游戏</span>\n          </button>\n          <button type=\"button\" :disabled=\"state.library.loading\" aria-label=\"刷新角色列表\" @click=\"onRefreshLibrary\">\n            <svg :class=\"{ spinning: state.library.loading }\" aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n              <path d=\"M20 11a8 8 0 1 0-2.34 5.66\" />\n              <path d=\"M20 5v6h-6\" />\n            </svg>\n            <span>刷新</span>\n          </button>\n          <div class=\"char-info-library-mobile-more\">\n            <button\n              type=\"button\"\n              aria-label=\"更多角色资料库操作\"\n              :aria-expanded=\"currentMobileMoreOpen\"\n              @click=\"currentMobileMoreOpen = !currentMobileMoreOpen\"\n            >\n              <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n                <circle cx=\"5\" cy=\"12\" r=\"1.5\" />\n                <circle cx=\"12\" cy=\"12\" r=\"1.5\" />\n                <circle cx=\"19\" cy=\"12\" r=\"1.5\" />\n              </svg>\n              <span>更多</span>\n            </button>\n            <div v-if=\"currentMobileMoreOpen\" class=\"char-info-library-mobile-more-menu\" role=\"menu\">\n              <button type=\"button\" role=\"menuitem\" @click=\"openSettingsFromCurrentMobileMore\">设置</button>\n            </div>\n          </div>\n        </nav>\n      </section>\n    </div>\n\n              <section class=\"char-info-library-current-viewer\" aria-label=\"当前聊天角色资料\">\n                <header class=\"char-info-library-header\">\n        <h2>{{ selectedCharacter?.name || '角色资料' }}</h2>\n        <div class=\"char-info-library-header-actions\">\n          <button class=\"char-info-library-list-action\" type=\"button\" @click=\"onOpenLibraryList\">\n            <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n              <path d=\"M5 6h14M5 12h14M5 18h14\" />\n              <circle cx=\"3\" cy=\"6\" r=\"0.75\" />\n              <circle cx=\"3\" cy=\"12\" r=\"0.75\" />\n              <circle cx=\"3\" cy=\"18\" r=\"0.75\" />\n            </svg>\n            <span>角色列表</span>\n          </button>\n          <button\n            v-if=\"selectedCharacter\"\n            class=\"char-info-library-list-action char-info-library-profile-action\"\n            type=\"button\"\n            @click=\"props.onEditCurrentChatCharacterProfile(selectedCharacter.name)\"\n          >\n            <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n              <path d=\"M4 19.5V15l10.8-10.8a2.1 2.1 0 0 1 3 0l2 2a2.1 2.1 0 0 1 0 3L9 20H4Z\" />\n              <path d=\"m13.5 5.5 5 5\" />\n            </svg>\n            <span>{{ selectedCharacter.hasProfileRecord ? '编辑档案' : '添加档案' }}</span>\n          </button>\n          <button\n            class=\"char-info-library-icon-action\"\n            type=\"button\"\n            :disabled=\"state.library.loading\"\n            :aria-label=\"state.library.loading ? '正在刷新角色资料' : '刷新角色资料'\"\n            @click=\"onRefreshLibrary\"\n          >\n            <svg :class=\"{ spinning: state.library.loading }\" aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n              <path d=\"M20 11a8 8 0 1 0-2.34 5.66\" />\n              <path d=\"M20 5v6h-6\" />\n            </svg>\n          </button>\n          <button\n            class=\"char-info-library-icon-action char-info-library-close-action\"\n            type=\"button\"\n            aria-label=\"关闭角色资料\"\n            @click=\"closeCharacterLibrary\"\n          >\n            <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n              <path d=\"m7 7 10 10M17 7 7 17\" />\n            </svg>\n          </button>\n        </div>\n      </header>\n\n      <main class=\"char-info-library-viewer\">\n        <ViewerApp\n          v-if=\"!state.library.viewerLoading && selectedCharacter && selectedCharacterYaml\"\n          :key=\"`${state.library.messageId}:${state.library.revision}:${selectedCharacter.name}`\"\n          :yaml-text=\"selectedCharacterYaml\"\n          :message-id=\"state.library.messageId\"\n          :effects-enabled=\"state.settings.effectsEnabled\"\n          :force-mobile-layout=\"state.settings.forceMobileLayout\"\n          :debug-enabled=\"state.settings.debugEnabled\"\n          :image-source-priority=\"activeImageSourcePriority\"\n          :entrance-quote-override=\"selectedCharacter.innerThought\"\n          embedded\n          read-only\n        />\n        <div v-else class=\"char-info-library-placeholder\">\n          <span aria-hidden=\"true\">◇</span>\n          <p>\n            {{\n              state.library.viewerLoading\n                ? '正在准备最新角色资料…'\n                : state.library.loading\n                  ? '正在读取角色资料…'\n                  : '暂时无法找到该角色的资料。'\n            }}\n          </p>\n        </div>\n      </main>\n\n      <nav class=\"char-info-library-viewer-mobile-dock\" aria-label=\"角色资料操作\">\n        <button type=\"button\" aria-label=\"返回角色列表\" @click=\"showLibraryListFromViewer\">\n          <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n            <path d=\"M5 6h14M5 12h14M5 18h14\" />\n            <circle cx=\"3\" cy=\"6\" r=\"0.75\" />\n            <circle cx=\"3\" cy=\"12\" r=\"0.75\" />\n            <circle cx=\"3\" cy=\"18\" r=\"0.75\" />\n          </svg>\n          <span>角色列表</span>\n        </button>\n        <button\n          v-if=\"selectedCharacter\"\n          type=\"button\"\n          :aria-label=\"selectedCharacter.hasProfileRecord ? '编辑角色档案' : '添加角色档案'\"\n          @click=\"props.onEditCurrentChatCharacterProfile(selectedCharacter.name)\"\n        >\n          <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n            <path d=\"M4 19.5V15l10.8-10.8a2.1 2.1 0 0 1 3 0l2 2a2.1 2.1 0 0 1 0 3L9 20H4Z\" />\n            <path d=\"m13.5 5.5 5 5\" />\n          </svg>\n          <span>{{ selectedCharacter.hasProfileRecord ? '编辑档案' : '添加档案' }}</span>\n        </button>\n        <button class=\"primary\" type=\"button\" aria-label=\"返回游戏并关闭角色资料\" @click=\"closeCharacterLibrary\">\n          <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\">\n            <path d=\"m4 11 8-7 8 7\" />\n            <path d=\"M6.5 10v10h11V10M9.5 20v-6h5v6\" />\n          </svg>\n          <span>返回游戏</span>\n        </button>\n      </nav>\n              </section>\n            </div>\n          </template>\n        </div>\n      </section>\n    </div>\n  </Teleport>\n\n  <Teleport v-if=\"state.settingsView\" :to=\"state.settingsView.host\">\n    <div\n      class=\"char-info-settings-backdrop\"\n      :class=\"managerThemeClass(state.settings.themeMode)\"\n      @click.self=\"onCloseSettings\"\n    >\n      <section\n        class=\"char-info-settings-dialog\"\n        role=\"dialog\"\n        aria-modal=\"true\"\n        aria-labelledby=\"char-info-settings-title\"\n      >\n        <header>\n          <h2 id=\"char-info-settings-title\">查看器设置</h2>\n          <button type=\"button\" aria-label=\"关闭查看器设置\" @click=\"onCloseSettings\">×</button>\n        </header>\n\n        <div class=\"char-info-settings-fields\">\n          <label>\n            <strong>显示楼层数</strong>\n            <input\n              v-model.number=\"floorLimitDraft\"\n              type=\"number\"\n              :min=\"MIN_ACTIVE_FLOOR_LIMIT\"\n              :max=\"MAX_ACTIVE_FLOOR_LIMIT\"\n              inputmode=\"numeric\"\n              @change=\"applySettings\"\n            />\n          </label>\n\n          <label>\n            <span>\n              <strong>每个消息楼层最多支持</strong>\n              <small>超过此数量时，该楼层的 CharInfo Viewer 将暂不渲染并弹出提示。</small>\n            </span>\n            <input\n              v-model.number=\"maxCardsPerMessageDraft\"\n              type=\"number\"\n              :min=\"MIN_MAX_CARDS_PER_MESSAGE\"\n              :max=\"MAX_MAX_CARDS_PER_MESSAGE\"\n              :disabled=\"unlimitedCardsPerMessageDraft\"\n              inputmode=\"numeric\"\n              @change=\"applySettings\"\n            />\n          </label>\n\n          <label>\n            <span>\n              <strong>不限单楼层数量</strong>\n              <small>警告：大量 Viewer 同时渲染可能明显增加性能与内存负担。</small>\n            </span>\n            <button\n              type=\"button\"\n              :class=\"{ 'char-info-settings-danger-active': unlimitedCardsPerMessageDraft }\"\n              @click=\"toggleUnlimitedCardsPerMessage\"\n            >\n              {{ unlimitedCardsPerMessageDraft ? '已开启无限制' : '无限制' }}\n            </button>\n          </label>\n\n          <label class=\"char-info-settings-switch\">\n            <span>\n              <strong>视觉特效</strong>\n              <small>关闭可降低手机负担。</small>\n            </span>\n            <input v-model=\"effectsEnabledDraft\" type=\"checkbox\" @change=\"applySettings\" />\n          </label>\n\n          <label>\n            <span>\n              <strong>界面主题</strong>\n              <small>深色与浅色使用同一套暖金视觉语言。</small>\n            </span>\n            <select v-model=\"themeModeDraft\" @change=\"applySettings\">\n              <option value=\"dark\">深色</option>\n              <option value=\"light\">浅色</option>\n            </select>\n          </label>\n\n          <label class=\"char-info-settings-switch\">\n            <span>\n              <strong>强制使用移动布局</strong>\n              <small>适用于较宽手机或窄屏浏览器；关闭时自动判断。</small>\n            </span>\n            <input v-model=\"forceMobileLayoutDraft\" type=\"checkbox\" @change=\"applySettings\" />\n          </label>\n\n          <label class=\"char-info-settings-switch\">\n            <span>\n              <strong>Debug 模式</strong>\n              <small>在浏览器 Console 输出图片来源尝试、失败、超时、切换与成功记录。</small>\n            </span>\n            <input v-model=\"debugEnabledDraft\" type=\"checkbox\" @change=\"applySettings\" />\n          </label>\n\n          <section class=\"char-info-settings-priority\" aria-labelledby=\"char-info-image-source-priority-label\">\n            <label class=\"char-info-settings-switch char-info-settings-priority-switch\">\n              <span>\n                <strong id=\"char-info-image-source-priority-label\">图片来源优先级</strong>\n                <small>开启后，查看器会优先尝试排在前面的网站；关闭时保持作者原本的图片顺序。</small>\n              </span>\n              <span class=\"char-info-settings-priority-toggle-wrap\">\n                <small>{{ imageSourcePriorityEnabledDraft ? '已开启' : '已关闭' }}</small>\n                <input\n                  v-model=\"imageSourcePriorityEnabledDraft\"\n                  class=\"char-info-settings-priority-toggle\"\n                  type=\"checkbox\"\n                  role=\"switch\"\n                  aria-label=\"启用图片来源优先级\"\n                  @change=\"toggleImageSourcePriority\"\n                />\n              </span>\n            </label>\n\n            <div v-if=\"imageSourcePriorityEnabledDraft\" class=\"char-info-settings-priority-editor\">\n              <p>一个输入框只填一个图片网站。数字越小，优先级越高。</p>\n              <div class=\"char-info-settings-priority-list\">\n                <div\n                  v-for=\"(priority, index) in imageSourcePriorityDraft\"\n                  :key=\"index\"\n                  class=\"char-info-settings-priority-row\"\n                >\n                  <span class=\"char-info-settings-priority-index\" aria-hidden=\"true\">{{ index + 1 }}</span>\n                  <input\n                    v-model.trim=\"imageSourcePriorityDraft[index]\"\n                    type=\"t